#define main movieclip_fixture_main
#include "standard_movieclip.c"
#undef main
#include <stdio.h>
static void hit(FVM_Context *c,FVM_Object *o,double x,double y,int shape,int expected){FVM_Value args[3],out;fvm_value_number(args,x);fvm_value_number(args+1,y);fvm_value_boolean(args+2,shape);assert(fvm_object_call(c,o,"hitTest",3,args,&out)==FVM_OK);assert(out.type==FVM_VALUE_BOOLEAN && out.boolean==expected);}
static void verify(FVM_Context *c,FVM_Object *o){hit(c,o,27,22,1,1);hit(c,o,33,28,0,1);hit(c,o,33,28,1,0);hit(c,o,45,40,1,0);}
int main(void){FVM_Config cfg;FVM_Runtime *rt=0;FVM_Context *c=0,*other=0;FVM_Object *root=0,*child=0;FVM_Channel *ch=0;FVM_Value args[3],out,value;FVM_Affine reflection={-1,0,0,1,5,0},normal={1,0,0,1,5,0};FVM_Result opened;assert(fvm_config_init(&cfg)==FVM_OK);assert(fvm_runtime_create(&cfg,&rt)==FVM_OK);assert(fvm_context_create(rt,&c)==FVM_OK);assert(fvm_context_create(rt,&other)==FVM_OK);assert(fvm_standard_install(c)==FVM_OK);assert(fvm_movieclip_create(c,"root",1,&root)==FVM_OK);assert(fvm_gc_pin(c,root)==FVM_OK);fvm_value_string(args,"triangle");fvm_value_number(args+1,1);assert(fvm_object_call(c,root,"createEmptyMovieClip",2,args,&out)==FVM_OK);child=out.object;fvm_value_number(&value,20);assert(fvm_object_set(c,root,"_x",&value)==FVM_OK);assert(fvm_object_set(c,root,"_y",&value)==FVM_OK);fvm_value_number(&value,5);assert(fvm_object_set(c,child,"_x",&value)==FVM_OK);fvm_value_number(args,0xff0000);assert(fvm_object_call(c,child,"beginFill",1,args,&out)==FVM_OK);coordinate(c,child,"moveTo",0,0);coordinate(c,child,"lineTo",10,0);coordinate(c,child,"lineTo",0,10);assert(fvm_object_call(c,child,"endFill",0,0,&out)==FVM_OK);verify(c,root);fvm_value_number(args,33);fvm_value_number(args+1,28);fvm_value_string(args+2,"yes");assert(fvm_object_call(c,root,"hitTest",3,args,&out)==FVM_OK && !out.boolean);hit(c,root,1e100,0,1,0);
fvm_value_undefined(&value);value.type=FVM_VALUE_OBJECT;value.object=root;assert(fvm_channel_create(&ch)==FVM_OK);assert(fvm_channel_send_value(c,ch,&value,0)==FVM_OK);assert(fvm_channel_receive_value(other,ch,&out,0)==FVM_OK);assert(fvm_gc_pin(other,out.object)==FVM_OK);assert(fvm_gc_collect(other,0)==FVM_OK);verify(other,out.object);fvm_channel_destroy(ch);
opened=fvm_channel_open_file("shape-hit-test.bin","w",&ch);if(opened==FVM_OK){assert(fvm_channel_send_value(c,ch,&value,0)==FVM_OK);fvm_channel_destroy(ch);assert(fvm_channel_open_file("shape-hit-test.bin","r",&ch)==FVM_OK);assert(fvm_channel_receive_value(other,ch,&out,0)==FVM_OK);assert(fvm_gc_pin(other,out.object)==FVM_OK);verify(other,out.object);fvm_channel_destroy(ch);assert(remove("shape-hit-test.bin")==0);}else assert(opened==FVM_UNSUPPORTED);
assert(fvm_movieclip_set_matrix(c,child,&reflection)==FVM_OK);hit(c,root,23,22,1,1);hit(c,root,17,28,0,1);hit(c,root,17,28,1,0);assert(fvm_movieclip_set_matrix(c,child,&normal)==FVM_OK);
assert(fvm_object_call(c,child,"clear",0,0,&out)==FVM_OK);fvm_value_number(args,2);fvm_value_number(args+1,0xff0000);assert(fvm_object_call(c,child,"lineStyle",2,args,&out)==FVM_OK);coordinate(c,child,"moveTo",0,0);coordinate(c,child,"lineTo",10,0);hit(c,root,30,20.8,1,1);hit(c,root,30,22,1,0);
fvm_context_destroy(other);fvm_context_destroy(c);fvm_runtime_destroy(rt);return 0;}
